#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Allocation {
    pub recipient: String,
    pub units: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Transfer {
    pub recipient: String,
    pub units: u64,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DistributionError {
    EmptyRecipient,
    ZeroAllocation,
    ArithmeticOverflow,
    InsufficientCredits,
    InsufficientFees,
}

pub fn build_transfers(
    allocations: &[Allocation],
) -> Result<Vec<Transfer>, DistributionError> {
    let mut transfers = Vec::with_capacity(allocations.len());
    for allocation in allocations {
        if allocation.recipient.is_empty() {
            return Err(DistributionError::EmptyRecipient);
        }
        if allocation.units == 0 {
            return Err(DistributionError::ZeroAllocation);
        }
        transfers.push(Transfer {
            recipient: allocation.recipient.clone(),
            units: allocation.units,
        });
    }
    Ok(transfers)
}

pub fn check_capacity(
    sender_credits: u64,
    fee_credits: u64,
    allocations: &[Allocation],
    fixed_fee: u64,
    new_recipient_count: u64,
    creation_fee: u64,
) -> Result<(), DistributionError> {
    let mut total = 0u64;
    for allocation in allocations {
        if allocation.recipient.is_empty() {
            return Err(DistributionError::EmptyRecipient);
        }
        if allocation.units == 0 {
            return Err(DistributionError::ZeroAllocation);
        }
        total = total
            .checked_add(allocation.units)
            .ok_or(DistributionError::ArithmeticOverflow)?;
    }

    let creation_total = new_recipient_count
        .checked_mul(creation_fee)
        .ok_or(DistributionError::ArithmeticOverflow)?;
    let required_fees = fixed_fee
        .checked_add(creation_total)
        .ok_or(DistributionError::ArithmeticOverflow)?;

    if total > sender_credits {
        return Err(DistributionError::InsufficientCredits);
    }
    if required_fees > fee_credits {
        return Err(DistributionError::InsufficientFees);
    }
    Ok(())
}
